package com.smartcanteen.api;
import com.smartcanteen.domain.MenuItem; import com.smartcanteen.service.MenuService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/menu") public class MenuController { final MenuService menus; MenuController(MenuService m){menus=m;} @GetMapping List<MenuItem> all(){return menus.all();} @PostMapping @PreAuthorize("hasRole('ADMIN')") MenuItem create(@RequestBody MenuItem item){item.id=null;return menus.save(item);} @PutMapping("/{id}") @PreAuthorize("hasRole('ADMIN')") MenuItem update(@PathVariable Long id,@RequestBody MenuItem item){item.id=id;return menus.save(item);} @DeleteMapping("/{id}") @PreAuthorize("hasRole('ADMIN')") void delete(@PathVariable Long id){menus.delete(id);} }
